9	static bool compareComplexVectors(const vector<complex<double>> &v1, const vector<complex<double>> &v2) {
10	    if(v1.size() != v2.size()) {
11	        return false;
12	    }
13	    for(unsigned int i=0;i<v1.size();i++) {
14	        if(abs(v1[i].real() - v2[i].real()) > 1e-14) {
15	            return false;
16	        }
17	        if(abs(v1[i].imag() - v2[i].imag()) > 1e-14) {
18	            return false;
19	        }
20	    }
21	    return true;
22	}
