27	    Fft::transform(data, false);
28	    vector<complex<double>> expectedResult{15, complex(-2.5, 3.440954801177934), complex(-2.5, 0.812299240582265), complex(-2.5, -0.812299240582265), complex(-2.5, -3.440954801177934)};
29	    QVERIFY(compareComplexVectors(data, expectedResult));
