5	Sparam::Sparam(const Tparam &t) {
6	    data = Eigen::MatrixXcd(2,2);
7	    set(1,1, t.get(1,2) / t.get(2,2));
8	    set(2,1, Type(1) / t.get(2,2));
9	    set(1,2, (t.get(1,1)*t.get(2,2) - t.get(1,2)*t.get(2,1)) / t.get(2,2));
10	    set(2,2, -t.get(2,1) / t.get(2,2));
11	}
