23	    : Sparam(a, Z0, Z0)
24	{
25	}
26	
27	Sparam::Sparam(const Zparam &Z, std::vector<Type> Z0n)
28	{
29	    if(Z.ports() != Z0n.size()) {
30	        throw std::runtime_error("number of supplied characteristic impedances does not match number of ports");
31	    }
32	    /* general formula for converting S parameters to Z parameters:
33	     * S = (sqrt(y)*Z*sqrt(y)-1)*(sqrt(y)*Z*sqrt(y)+1)^-1
34	     * with:
35	     * Z = Z parameter matrix
36	     * 1 = identity matrix
37	     * sqrt(y) = diagonal matrix with the root of characteristic admittances as it non-zero elements
38	     */
39	    // create identity matrix
40	    auto ident = Eigen::MatrixXcd::Identity(Z.ports(), Z.ports());
41	    // create sqrt(y) matrix
42	    Eigen::MatrixXcd sqrty = Eigen::MatrixXcd::Zero(Z.ports(), Z.ports());
43	    // fill with characteristic admittance
44	    for(unsigned int i=0;i<Z.ports();i++) {
45	        sqrty(i, i) = 1.0/(sqrt(Z0n[i]));
46	    }
47	    // apply formula
48	    auto yZy = sqrty*Z.data*sqrty;
49	    data = (yZy-ident)*(yZy+ident).inverse();
50	}
51	
52	Sparam::Sparam(const Zparam &Z, Type Z0)
53	    : Sparam(Z, std::vector<Type>(Z.ports(), Z0))
54	{
55	
56	}
57	
58	void Sparam::swapPorts(unsigned int p1, unsigned int p2)
59	{
60	    data.col(p1-1).swap(data.col(p2-1));
61	    data.row(p1-1).swap(data.row(p2-1));
62	}
63	
64	Sparam Sparam::reduceTo(std::vector<unsigned int> ports) const
65	{
66	    auto ret = Sparam(ports.size());
67	    for(unsigned int from=0;from<ports.size();from++) {
68	        for(unsigned int to=0;to<ports.size();to++) {
69	            ret.data(to, from) = get(ports[to], ports[from]);
70	        }
71	    }
72	    return ret;
73	}
74	
75	ABCDparam::ABCDparam(const Sparam &s, Type Z01, Type Z02)
76	{
77	    if(s.ports() != 2) {
78	        throw std::runtime_error("Can only create ABCD parameter from 2 port S parameters");
79	    }
80	    data = Eigen::MatrixXcd(2,2);
81	    auto denom = 2.0*s.get(2,1)*sqrt(real(Z01)*real(Z02));
82	    set(1,1, ((conj(Z01)+s.get(1,1)*Z01)*(1.0-s.get(2,2))+s.get(1,2)*s.get(2,1)*Z01) / denom);
83	    set(1,2, ((conj(Z01)+s.get(1,1)*Z01)*(conj(Z02)+s.get(2,2)*Z02)-s.get(1,2)*s.get(2,1)*Z01*Z02) / denom);
84	    set(2,1, ((1.0-s.get(1,1))*(1.0-s.get(2,2))-s.get(1,2)*s.get(2,1)) / denom);
85	    set(2,2, ((1.0-s.get(1,1))*(conj(Z02)+s.get(2,2)*Z02)+s.get(1,2)*s.get(2,1)*Z02) / denom);
86	}
87	
88	Tparam::Tparam(const Sparam &s)
89	{
90	    if(s.ports() != 2) {
91	        throw std::runtime_error("Can only create ABCD parameter from 2 port S parameters");
92	    }
93	    data = Eigen::MatrixXcd(2,2);
94	    set(1,1, -(s.get(1,1)*s.get(2,2) - s.get(1,2)*s.get(2,1)) / s.get(2,1));
95	    set(1,2, s.get(1,1) / s.get(2,1));
96	    set(2,1, -s.get(2,2) / s.get(2,1));
97	    set(2,2, 1.0 / s.get(2,1));
98	}
99	
100	ABCDparam::ABCDparam(const Sparam &s, Type Z0)
101	    : ABCDparam(s, Z0, Z0)
